kground:#ffffff0b;line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere;animation:msg-in .16s ease-out}.msg.sent{align-self:flex-end;background:linear-gradient(135deg,#83ecc424,#91a9ff1e);border-bottom-right-radius:4px}.msg.received{align-self:flex-start;border-bottom-left-radius:4px}.msg-time{display:block;color:var(--muted);font-size:.65rem;text-align:right;margin-top:6px}.msg.read .msg-time:after{content:'  ✓✓';color:var(--accent)}.msg-img{display:block;max-width:min(350px,100%);max-height:300px;border-radius:10px}.file-link{color:var(--accent)}.msg-tools{display:flex;gap:4px;justify-content:flex-end;flex-wrap:wrap;margin-top:7px}.msg-tools button,.reaction-chip{border:1px solid var(--line);border-radius:99px;background:#0002;padding:3px 7px;color:var(--text);cursor:pointer}.reaction-bar{opacity:.55;transition:opacity .15s}.msg:hover .reaction-bar,.msg:focus-within .reaction-bar{opacity:1}.typing-indicator{display:none;align-items:center;gap:8px;color:var(--muted);font-size:.75rem;padding:0 20px 8px}.typing-indicator.visible{display:flex}.typing-dots{display:flex;gap:3px}.typing-dots i{width:5px;height:5px;border-radius:50%;background:var(--accent);animation:bounce 1s infinite}.typing-dots i:nth-child(2){animation-delay:.15s}.typing-dots i:nth-child(3){animation-delay:.3s}.input-zone{display:flex;align-items:center;gap:8px;padding:12px 15px calc(12px + env(safe-area-inset-bottom));border-top:1px solid var(--line);background:#090d17ed;backdrop-filter:blur(16px);flex:none}.input-zone.hidden{display:none}.input{flex:1;min-width:0;padding:12px;border:1px solid var(--line);border-radius:12px;background:#080d18;color:var(--text)}.composer-options{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:.72rem;white-space:nowrap}.composer-options input{accent-color:var(--accent)}.send{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#08120e;border:0;font-weight:700}.empty{margin:auto;text-align:center;padding:20px;color:var(--muted);line-height:1.7}.hidden{display:none!important}.modal-overlay{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:20px;background:#02050bcc;backdrop-filter:blur(9px)}.modal{width:min(480px,100%);max-height:90dvh;overflow:auto;padding:24px;border-radius:20px}.modal h2{margin:0 0 7px;font:600 1.35rem 'Space Grotesk'}.modal p{color:var(--muted);line-height:1.5}.setting-row{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:12px 0;border-top:1px solid var(--line);color:var(--muted)}.setting-row select{padding:8px;background:#101728;color:var(--text);border:1px solid var(--line);border-radius:9px}.swatches{display:flex;gap:7px}.swatch{width:25px;height:25px;border:0;border-radius:50%;cursor:pointer}.swatch[data-value=glass]{background:linear-gradient(135deg,#83ecc4,#91a9ff)}.swatch[data-value=aurora]{background:linear-gradient(135deg,#65fbd2,#b59aff)}.swatch[data-value=midnight]{background:linear-gradient(135deg,#c2a8ff,#75bcff)}.swatch[data-value=rose]{background:linear-gradient(135deg,#ffb4d2,#c6a0ff)}.danger-btn{color:var(--danger)!important}.toast{position:fixed;z-index:50;bottom:22px;left:50%;transform:translate(-50%,12px);opacity:0;background:#182136;border:1px solid var(--line);padding:11px 16px;border-radius:12px;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.once-overlay{position:fixed;inset:0;z-index:40;display:grid;place-items:center;background:#050812f5;padding:20px}.once-card{width:min(600px,100%);padding:22px;border:1px solid var(--line);border-radius:20px;background:#111827}.once-body{min-height:100px;display:grid;place-items:center;overflow-wrap:anywhere}.once-body img{max-width:100%;max-height:65dvh}body[data-theme=aurora]{--bg:#071218;--accent:#65fbd2;--accent2:#b59aff}body[data-theme=midnight]{--bg:#080a13;--accent:#c2a8ff;--accent2:#75bcff}body[data-theme=rose]{--bg:#140b15;--accent:#ffb4d2;--accent2:#c6a0ff}body[data-theme=light]{color-scheme:light;--bg:#edf2f