</style></head><body><div class="app"><aside class="sidebar glass" id="sidebar"><div class="side-head"><a href="index.php" class="brand"><img src="sdpGhostlink.png" alt=""><span>GhostLink</span></a><p class="subline">Private conversations, made personal.</p><input id="searchUser" class="search" type="search" placeholder="Search people…" aria-label="Search contacts"></div><div class="list-label">Contacts</div><div id="userList" class="user-list"><div class="empty">Finding people…</div></div><div class="side-foot"><button class="side-link" onclick="showProfile()">Profile</button><button class="side-link" onclick="showSettings()">Settings</button><a class="side-link" href="index.php?page=usage">Guide</a><a class="side-link abort" href="logout.php">Sign out</a></div></aside><main class="chat glass"><header class="chat-head"><div class="head-left"><button class="icon-btn mobile-menu" onclick="toggleSidebar()" aria-label="Open contacts">☰</button><div><div class="target" id="chatTitle">Choose someone to chat</div><div class="target-sub" id="chatSubtitle">Select a contact to begin</div></div></div><div class="head-actions"><span class="key-label">Shared key</span><input id="secretKey" class="key-input" type="password" placeholder="Shared key" autocomplete="off" aria-label="Shared key"><button class="icon-btn" type="button" onclick="showSettings()" title="Settings">⚙</button><button class="icon-btn" type="button" onclick="showProfile()" title="Profile">☺</button></div></header><div class="toolbar"><input id="chatSearch" class="chat-search" type="search" placeholder="Search this conversation…" aria-label="Search messages"><button id="clearChat" class="tool-btn danger-btn" type="button">Clear chat</button></div><section class="messages" id="msgBox" aria-live="polite"><div class="empty">Select a person to start a conversation.</div></section><div id="typingIndicator" class="typing-indicator"><span id="typingName">Contact</span> is typing <span class="typing-dots"><i></i><i></i><i></i></span></div><form class="input-zone hidden" id="inputZone"><button type="button" class="attach" id="attachButton" title="Attach file">＋</button><input id="msgInput" class="input" placeholder="Write a message…" autocomplete="off" aria-label="Message"><label class="composer-options"><input type="checkbox" id="viewOnce">View once</label><button class="send" id="sendButton">Send ↗</button></form></main></div><input id="fileInput" type="file" hidden><div id="toast" class="toast" role="status" aria-live="polite"></div>
<div id="settingsModal" class="modal-overlay hidden"><section class="modal glass" role="dialog" aria-modal="true"><h2>Advanced settings</h2><p>Personalise this device's chat experience.</p><div class="setting-row"><span>Theme</span><div class="swatches"><button class="swatch" data-theme="glass" aria-label="Glass theme"></button><button class="swatch" data-theme="aurora" aria-label="Aurora theme"></button><button class="swatch" data-theme="midnight" aria-label="Midnight theme"></button><button class="swatch" data-theme="rose" aria-label="Rose theme"></button><button class="swatch" data-theme="light" aria-label="Light theme" style="background:linear-gradient(135deg,#fff,#8ca9ff)"></button></div></div><div class="setting-row"><span>Message spacing</span><select id="densitySetting"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></div><div class="setting-row"><span>Text size</span><select id="fontSetting"><option value="normal">Normal</option><option value="large">Large</option></select></div><div class="setting-row"><span>Motion effects</span><input id="motionSetting" type="checkbox" checked></div><div class="setting-row"><span>Notification sound</span><input id="soundSetting" type="checkbox" checked></div><div class="setting-row"><span>Confirm before clear</span><input id="confirmSetting" type="checkbox" checked></div><button class="send" onclick="closeSettings()">Done</button></section></div><div id="profileModal" class="modal-overlay hidden"><section class="modal glass" role="dialog" aria-modal="true"><h2>Your profile</h2><input id="editBio" placeholder="Short bio" maxlength="255"><input id="editPhone" placeholder="Phone number"><button class="send" onclick="saveProfile()">Save</button></section></div><div id="onceOverlay" class="once-overlay hidden"><section class="once-card"><h2>View once</h2><p id="onceCountdown">Closes and is removed after viewing.</p><div id="onceBody" class="once-body"></div><button class="send" id="closeOnce">Close & destroy</button></section></div><audio id="notifySound" src="https://actions.google.com/sounds/v1/alarms/beep_short.ogg" preload="none"></audio>
<script>
'use strict';let peer=null,peerName='',poll=null,presencePoll=null,typingStop=null,viewTimer=null,requestToken=0,toastTimer=null,known=new Set(),pendingAttachment='';const $=id=>document.getElementById(id),EMOJIS=['👍','❤️','😂','😮','😢','🎉'];
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)}async function post(data){const f=new FormData();for(const [k,v]of Object.entries(data))f.append(k,v);const r=await fetch('engine.php',{method:'POST',body:f,credentials:'same-origin'});return r.text()}function auth(s){if(s.trim()==='ACCESS DENIED'){location.href='index.php?page=login&error=Session%20Expired';return false}return true}function toggleSidebar(){$('sidebar').classList.toggle('active')}
const defaultPrefs={theme:'glass',density:'comfortable',font:'normal',motion:true,sound:true,confirm:true};function prefs(){return{theme:document.body.dataset.theme||'glass',density:$('densitySetting').value,font:$('fontSetting').value,motion:$('motionSetting').checked,sound:$('soundSetting').checked,confirm:$('confirmSetting').checked}}function savePrefs(){const p=prefs();try{localStorage.setItem('ghostlink-polish',JSON.stringify(p))}catch(e){}applyPrefs(p)}function applyPrefs(p){document.body.dataset.theme=p.theme;document.body.dataset.density=p.density;document.body.dataset.fontSize=p.font;document.body.dataset.motion=p.motion?'on':'off';$('densitySetting').value=p.density;$('fontSetting').value=p.font;$('motionSetting').checked=p.motion;$('soundSetting').checked=p.sound;$('confirmSetting').checked=p.confirm;document.querySelector('meta[name=theme-color]').content=p.theme==='light'?'#edf2f8':p.theme==='aurora'?'#071218':p.theme==='rose'?'#140b15':p.theme==='midnight'?'#080a13':'#090d17'}function loadPrefs(){let p={};try{p=JSON.parse(localStorage.getItem('ghostlink-polish')||'{}')}catch(e){}applyPrefs({...defaultPrefs,...p})}window.showSettings=()=>$('settingsModal').classList.remove('hidden');window.closeSettings=()=>$('settingsModal').classList.add('hidden');document.querySelectorAll('.swatch').forEach(b=>b.onclick=()=>{document.body.dataset.theme=b.dataset.theme;savePrefs()});['densitySetting','fontSetting','motionSetting','soundSetting','confirmSetting'].forEach(id=>$(id).addEventListener('change',savePrefs));
function renderContacts(html){const list=$('userList');if(list.dataset.html===html)return;list.dataset.html=html;list.innerHTML=html;list.querySelectorAll('.user-card').forEach(b=>{if(b.dataset.userId===peer)b.classList.add('active');b.onclick=()=>openChat(b.dataset.userId,b.dataset.username)})}async function fetchUsers(){try{const s=await post({mode:'get_users',search:$('searchUser').value});if(auth(s))renderContacts(s)}catch(e){}}
function dateLabel(iso){const d=new Date(iso+'T00:00:00'),today=new Date();today.setHours(0,0,0,0);const yesterday=new Date(today);yesterday.setDate(today.getDate()-1);if(d.getTime()===today.getTime())return'Today';if(d.getTime()===yesterday.getTime())return'Yesterday';return d.toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'})}function appendContent(el,text){if(text.startsWith('FILE:')){const path=text.slice(5).trim();if(!/^uploads\/[\w.-]+$/.test(path)){el.append(document.createTextNode('Attachment unavailable'));return}const ext=path.split('.').pop().toLowerCase();if(['jpg','jpeg','png','gif','webp'].includes(ext)){const im=document.createElement('img');im.src=path;im.alt='Shared image';im.className='msg-img';im.loading='lazy';el.append(im)}else{const a=document.createElement('a');a.href=path;a.target='_blank';a.rel='noopener noreferrer';a.className='file-link';a.textContent='↗ Open '+ext.toUpperCase()+' file';el.append(a)}return}el.append(document.createTextNode(text))}
async function react(id,emoji){const r=await post({mode:'toggle_reaction',msg_id:id,reaction:emoji});if(r.trim()==='ok')fetchMessages(requestToken)}function buildMessage(row){const node=document.createElement('article');node.id=row.id;node.className='msg '+(row.classList.contains('sent')?'sent':'received');node.dataset.encrypted=row.dataset.enc||'';node.dataset.once=row.dataset.viewOnce||'0';const mine=row.classList.contains('sent'),id=row.id.slice(4),text=(()=>{if(!row.dataset.enc||!$('secretKey').value)return'';try{return CryptoJS.AES.decrypt(row.dataset.enc,$('secretKey').value).toString(CryptoJS.enc.Utf8)}catch(e){return''}})();if(node.dataset.once==='1'&&!mine){const b=document.createElement('button');b.className='send';b.textContent='Open view-once message';b.onclick=()=>openOnce(id);node.append(b)}else if(text)appendContent(node,text);else node.append(document.createTextNode($('secretKey').value?'Unable to decrypt. Check the shared key.':'Enter your shared key to read this message.'));if(row.dataset.time&&!node.dataset.once){const time=document.createElement('small');time.className='msg-time';time.textContent=row.dataset.time+(mine?(row.dataset.read==='1'?' · Read ✓✓':' · Sent ✓'):'');node.append(time)}const bar=document.createElement('div');bar.className='msg-tools reaction-bar';EMOJIS.forEach(emoji=>{const b=document.createElement('button');b.type='button';b.textContent=emoji;b.title='React '+emoji;b.onclick=()=>react(id,emoji);bar.append(b)});node.append(bar);try{const reactions=JSON.parse(row.dataset.reactions||'[]');if(reactions.length){const summary=document.createElement('div');summary.className='msg-tools';reactions.forEach(r=>{const b=document.createElement('span');b.className='reaction-chip';b.textContent=r.emoji+' '+r.count;summary.append(b)});node.append(summary)}}catch(e){}if(mine){const del=document.createElement('button');del.type='button';del.className='msg-tools reaction-chip danger-btn';del.textContent='Delete';del.onclick=()=>deleteMessage(id);node.append(del)}return node}
function openChat(id,name){peer=String(id);peerName=name||'Contact';$('chatTitle').textContent=peerName;$('typingName').textContent=peerName;$('chatSubtitle').textContent='🔒 Encrypted in your browser';$('inputZone').classList.remove('hidden');$('sidebar').classList.remove('active');$('userList').querySelectorAll('.user-card').forEach(x=>x.classList.toggle('active',x.dataset.userId===peer));$('msgBox').innerHTML='<div class="empty">Loading conversation…</div>';known=new Set();if(poll)clearInterval(poll);if(presencePoll)clearInterval(presencePoll);const token=++requestToken;fetchMessages(token);poll=setInterval(()=>fetchMessages(token),2500);presencePoll=setInterval(pollPresence,1500)}
async function fetchMessages(token=requestToken){if(!peer||token!==requestToken)return;try{const html=await post({mode:'get_msgs',target:peer});if(token!==requestToken||!auth(html))return;const temp=document.createElement('div');temp.innerHTML=html;const rows=[...temp.querySelectorAll('.msg')],box=$('msgBox'),near=box.scrollHeight-box.scrollTop-box.clientHeight<100,next=new Set();let incoming=false;const fragment=document.createDocumentFragment();let lastDate='';for(const row of rows){const id=row.id;if(!id)continue;next.add(id);const existing=document.getElementById(id),sig=(row.dataset.enc||'')+'|'+row.dataset.reactions+'|'+row.dataset.read+'|'+row.dataset.viewOnce;if(existing&&existing.dataset.sig===sig){if(row.dataset.date!==lastDate){const divider=document.createElement('div');divider.className='date-separator';divider.textContent=dateLabel(row.dataset.date);fragment.append(divider);lastDate=row.dataset.date}fragment.append(existing);continue}if(!known.has(id)&&row.classList.contains('received'))incoming=true;if(row.dataset.date!==lastDate){const divider=document.createElement('div');divider.className='date-separator';divider.textContent=dateLabel(row.dataset.date);fragment.append(divider);lastDate=row.dataset.date}const node=buildMessage(row);node.dataset.sig=sig;fragment.append(node)}const oldMap=new Map([...box.querySelectorAll('.msg')].map(n=>[n.id,n]));for(const [id,n]of oldMap)if(!next.has(id))n.remove();if(rows.length){box.querySelector('.empty')?.remove();const marker=box.querySelector('.date-separator');if(!marker||next.size!==known.size||[...rows].some(r=>!oldMap.has(r.id)))box.replaceChildren(fragment)}else if(!box.querySelector('.empty'))box.innerHTML='<div class="empty">No messages yet. Send the first one.</div>';if(near||known.size===0)box.scrollTop=box.scrollHeight;if(incoming&&$('soundSetting').checked)$('notifySound').play().catch(()=>{});known=next}catch(e){}}
let lastTypingSent=0;async function sendTyping(active){if(!peer)return;const now=Date.now();if(active&&now-lastTypingSent<1200)return;lastTypingSent=now;try{await post({mode:'typing',target:peer,typing:active?1:0})}catch(e){}}async function pollPresence(){if(!peer)return;try{const result=await post({mode:'get_typing',target:peer});$('typingIndicator').classList.toggle('visible',result.trim()==='1')}catch(e){}}
async function sendMessage(){const input=$('msgInput'),text=input.value,key=$('secretKey').value;if(!peer)return toast('Choose a contact first.');if(!text.trim())return;if(!key.trim())return toast('Enter your shared key first.');if(typeof CryptoJS==='undefined')return toast('Encryption library unavailable.');const btn=$('sendButton');btn.disabled=true;try{const encrypted=CryptoJS.AES.encrypt(text,key).toString(),r=await post({mode:'send_msg',target:peer,msg:encrypted,view_once:$('viewOnce').checked?1:0,attachment_path:pendingAttachment});if(!auth(r))return;if(r.trim()==='sent'){input.value='';$('viewOnce').checked=false;sendTyping(false);await fetchMessages()}else toast(r)}catch(e){toast('Message could not be sent.')}finally{btn.disabled=false;input.focus()}}
async function uploadFile(){const f=$('fileInput');if(!f.files.length)return;const file=f.files[0];if(file.size>25000000){f.value='';return toast('File exceeds the 25 MB limit.')}if(!peer||!$('secretKey').value.trim()){f.value='';return toast('Choose a chat and enter your shared key first.')}try{const form=new FormData();form.append('file',file);const response=await fetch('upload.php',{method:'POST',body:form,credentials:'same-origin'});const path=(await response.text()).trim();if(path.startsWith('error:'))return toast(path);pendingAttachment=path;$('msgInput').value='FILE:'+path;await sendMessage()}catch(e){toast('Upload failed.')}finally{f.value='';pendingAttachment='';$('msgInput').value=''}}
async function openOnce(id){try{const raw=await post({mode:'open_view_once',msg_id:id});if(!auth(raw))return;const data=JSON.parse(raw),plain=CryptoJS.AES.decrypt(data.message,$('secretKey').value).toString(CryptoJS.enc.Utf8);if(!plain)throw Error('Could not decrypt. Check the shared key.');$('onceBody').replaceChildren();if(plain.startsWith('FILE:')){const path=plain.slice(5).trim();if(!/^uploads\/[\w.-]+$/.test(path))throw Error('Attachment unavailable');const ext=path.split('.').pop().toLowerCase();if(['jpg','jpeg','png','gif','webp'].includes(ext)){const im=document.createElement('img');im.src=path;im.alt='View-once image';$('onceBody').append(im)}else{$('onceBody').textContent='Attachment: '+ext.toUpperCase()}}else $('onceBody').textContent=plain;$('onceOverlay').classList.remove('hidden');let seconds=15;clearInterval(viewTimer);$('onceCountdown').textContent='This closes and is destroyed in '+seconds+' seconds.';viewTimer=setInterval(()=>{seconds--;$('onceCountdown').textContent=seconds>0?'This closes and is destroyed in '+seconds+' seconds.':'Removing…';if(seconds<=0)closeOnce(id)},1000);$('closeOnce').onclick=()=>closeOnce(id)}catch(e){toast(e.message||'View-once content is unavailable.')}}let closingOnce=false;async function closeOnce(id){if(closingOnce)return;closingOnce=true;clearInterval(viewTimer);$('onceOverlay').classList.add('hidden');$('onceBody').replaceChildren();try{await post({mode:'finish_view_once',msg_id:id})}finally{closingOnce=false;fetchMessages()}}
async function deleteMessage(id){if(!confirm('Delete this message for everyone?'))return;const r=await post({mode:'delete_msg',msg_id:id});if(r.trim()==='deleted'){document.getElementById('msg_'+id)?.remove();known.delete('msg_'+id);toast('Message deleted.')}}$('clearChat').onclick=async()=>{if(!peer)return toast('Select a conversation first.');if(prefs().confirm&&!confirm('Delete this conversation and all attachments for both people?'))return;const r=await post({mode:'clear_chat',target:peer});if(r.trim()==='cleared'){known.clear();$('msgBox').innerHTML='<div class="empty">Conversation cleared.</div>';toast('Conversation cleared for both people.')}};
$('chatSearch').addEventListener('input',()=>{const q=$('chatSearch').value.toLocaleLowerCase();document.querySelectorAll('#msgBox .msg').forEach(m=>{m.classList.remove('search-match');if(!q)return;let text=m.textContent.toLocaleLowerCase();try{text+=' '+CryptoJS.AES.decrypt(m.dataset.encrypted||'',$('secretKey').value).toString(CryptoJS.enc.Utf8).toLocaleLowerCase()}catch(e){}if(text.includes(q))m.classList.add('search-match')})});window.showProfile=async()=>{$('profileModal').classList.remove('hidden');try{const r=await post({mode:'get_my_profile'});if(auth(r)){const p=JSON.parse(r);$('editBio').value=p.bio||'';$('editPhone').value=p.phone||''}}catch(e){toast('Profile load failed')}};window.saveProfile=async()=>{const r=await post({mode:'update_profile',bio:$('editBio').value,phone:$('editPhone').value});if(r.trim()==='updated'){$('profileModal').classList.add('hidden');toast('Profile saved');fetchUsers()}};
$('inputZone').addEventListener('submit',e=>{e.preventDefault();sendMessage()});$('attachButton').onclick=()=>$('fileInput').click();$('fileInput').addEventListener('change',uploadFile);$('searchUser').addEventListener('input',fetchUsers);$('secretKey').addEventListener('input',()=>peer&&fetchMessages());$('msgInput').addEventListener('input',()=>{if(!$('msgInput').value.trim()){clearTimeout(typingStop);sendTyping(false);return}sendTyping(true);clearTimeout(typingStop);typingStop=setTimeout(()=>sendTyping(false),2200)});document.querySelectorAll('.modal-overlay').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.add('hidden')}));window.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.modal-overlay').forEach(m=>m.classList.add('hidden'));$('sidebar').classList.remove('active');if(!$('onceOverlay').classList.contains('hidden')){const id=document.querySelector('#msgBox .msg[data-once="1"]')?.id.slice(4);if(id)closeOnce(id)}}});loadPrefs();fetchUsers();setInterval(fetchUsers,7000);
</script></body></html>
